304: 	// previous render's value, when config and status arrive together.
305: 	useEffect(() => {
306: 		if (!data || !shouldSeedLLMPrompt(isLLMFallbackEnabled, defaultLLMPrompt, getValues("llm.prompt") ?? "", promptEdited.current)) return;
307: 		setValue("llm.prompt", defaultLLMPrompt, { shouldDirty: false });
308: 	}, [data, isLLMFallbackEnabled, defaultLLMPrompt, livePrompt, getValues, setValue]);
309: 
310: 	const handleDiscard = () => {
311: 		promptEdited.current = false;
312: 		if (data) reset(toFormValues(data));
313: 		setSubmitError(null);
314: 	};
315: 
316: 	const handleRestoreDefaults = () => {
317: 		if (!canUpdate) return;
318: 		setSubmitError(null);
319: 		resetConfig()
320: 			.unwrap()
321: 			.then((defaults) => {
322: 				promptEdited.current = false;
323: 				reset(toFormValues(defaults));
324: 				toast.success("Reset to defaults", { position: "top-right" });
325: 			})
326: 			.catch((err) => {
327: 				setSubmitError(`Couldn’t restore the default phrases. ${getErrorMessage(err)}`);
328: 			});
329: 	};
330: 
331: 	const handleRetrySemanticWarmup = () => {
332: 		if (!canUpdate) return;
333: 		retrySemanticWarmup()
334: 			.unwrap()
335: 			.then(() => {
336: 				toast.success("Semantic warmup restarted", { position: "top-right" });
337: 				void refetchStatus();
338: 			})
339: 			.catch((err) => {
340: 				toast.error(`Couldn’t retry semantic warmup. ${getErrorMessage(err)}`, { position: "top-right" });
341: 			});
342: 	};
343: 
344: 	const onValid = (values: AnalyzerFormValues) => {
345: 		if (!canUpdate) return;
346: 		setSubmitError(null);
347: 		// The endpoint replaces the whole record and rejects a semantic block
348: 		// without a provider and model, so an unconfigured classifier omits it
349: 		// entirely and saves the phrase lists alone.
350: 		//
351: 		// A half-filled form block falls back to what is stored rather than
352: 		// omitting the block. The embedding controls live in a sheet, so they are
353: 		// unmounted for the whole of a phrase-only save — the exact case where
354: 		// dropping the block would silently clear a working classifier the
355: 		// operator never opened. Nothing here removes it on purpose: the provider
356: 		// select has no clear option, and Restore defaults goes through its own
357: 		// endpoint.
358: 		// The helper preserves saved sheet-only settings and omits session when
359: 		// disabled. Nil is already the wire-level disabled state; avoiding the
360: 		// additive field keeps unrelated edits compatible with older gateways.
361: 		const payload = toAnalyzerPayload(values, data);
362: 		updateConfig(payload)
363: 			.unwrap()
364: 			.then((res) => {
365: 				promptEdited.current = false;
366: 				reset(toFormValues(res));
367: 				setEmbeddingSheetOpen(false);
368: 				toast.success("Configuration saved", { position: "top-right" });
369: 			})
370: 			.catch((err) => {
371: 				setSubmitError(`Couldn’t save the Complexity Router configuration. ${getErrorMessage(err)}`);
372: 			});
373: 	};
374: 
375: 	// Saving from inside the sheet still submits the whole configuration, so a
376: 	// phrase error would report behind it. Close the sheet in that case,
377: 	// otherwise the message is hidden under the overlay. An llm error opens the
378: 	// sheet instead: selecting the llm classifier without configuring it fails
379: 	// on fields that live in the sheet the operator may never have opened.
380: 	const submit = handleSubmit(onValid, (formErrors) => {
381: 		if (formErrors.semantic || formErrors.llm) {
382: 			setEmbeddingSheetOpen(true);
383: 		} else {
384: 			setEmbeddingSheetOpen(false);
385: 		}
386: 	});
387: 
388: 	if (isLoading && !data) {
389: 		return <FullPageLoader />;
390: 	}
