398: 					Retry
399: 				</Button>
400: 			</div>
401: 		);
402: 	}
403: 
404: 	if (!data) {
405: 		return (
406: 			<div className="mx-auto w-full max-w-7xl space-y-4 px-4 pt-6 sm:px-6 sm:pt-8 lg:px-14">
