415: 	const keywordErrors = errors.keywords;
416: 	const hasErrors = Boolean(keywordErrors || errors.semantic || errors.llm || errors.session);
417: 	const canSave = canUpdate && isDirty && !isResetting && !(isSubmitted && hasErrors);
418: 
419: 	// Rendered on the page and again inside the sheet: the re-embed cost is a
420: 	// consequence of saving, and either surface can trigger the save.
