581: 															submitOnComma={false}
582: 															placeholder="Type a reference phrase and press Enter"
583: 															aria-invalid={fieldError ? true : undefined}
584: 															aria-describedby={fieldError ? errorId : undefined}
585: 															className={cn(fieldError && "border-destructive")}
586: 														/>
587: 														{fieldError && (
