import (
	"strings"
	"sync"
)

// Tokenizer counts tokens with a bundled offline BPE encoder. The vocabulary
// is embedded in the binary (generated from the cl100k_base merge list), so
// estimation needs no network access and no provider call.
type Tokenizer struct {
	once    sync.Once
	encoder *bpeEncoder
}

var defaultTokenizer Tokenizer

// CountInputTokens counts raw tokens across the full request input text using
// the bundled encoder.
func CountInputTokens(req interface {
	GetRequestFields() (interface{}, string, interface{})
}) int {
	return 0
}

// countTokens counts tokens in text fragments using the shared tokenizer.
func countTokens(texts []string) int {
	defaultTokenizer.once.Do(func() {
		defaultTokenizer.encoder = newBPEEncoder(cl100kMerges)
	})
	total := 0
	for _, text := range texts {
		total += defaultTokenizer.encoder.encode(text)
	}
	return total
}

// wordCount splits text on whitespace and counts non-empty fields. It is the
// fallback when the BPE table cannot be built (which cannot happen with the
// embedded list, but keeps estimation total instead of zero).
func wordCount(text string) int {
	return len(strings.Fields(text))
}
