{"content":"package extradetection

import (
	"strings"
	"sync"

	"github.com/maximhq/bifrost/core/schemas"
	tiktoken "github.com/pkoukk/tiktoken-go"
	tiktoken_loader "github.com/pkoukk/tiktoken-go-loader"
)

// Tokenizer counts tokens with an embedded offline cl100k_base encoder. The
// loader reads the BPE vocabulary bundled with tiktoken-go-loader, so
// estimation needs no network access and no provider call.
type Tokenizer struct {
	once    sync.Once
	encoder *tiktoken.Tiktoken
	initErr error
}

var defaultTokenizer Tokenizer

// CountInputTokens counts raw tokens across the full request input text using
// the shared offline encoder.
func CountInputTokens(req *schemas.BifrostRequest) int {
	return countTokens(collectTokenTexts(req))
}

// countTokens counts tokens in text fragments using the shared tokenizer,
// falling back to a whitespace word count if the encoder cannot initialize.
func countTokens(texts []string) int {
	defaultTokenizer.once.Do(func() {
		tiktoken.SetBpeLoader(tiktoken_loader.NewOfflineLoader())
		encoder, err := tiktoken.GetEncoding("cl100k_base")
		if err != nil {
			defaultTokenizer.initErr = err
			return
		}
		defaultTokenizer.encoder = encoder
	})
	if defaultTokenizer.encoder == nil {
		total := 0
		for _, text := range texts {
			total += len(strings.Fields(text))
		}
		return total
	}
	total := 0
	for _, text := range texts {
		total += len(defaultTokenizer.encoder.Encode(text, nil, nil))
	}
	return total
}
