/**
 * Routing Rules Page
 * Main container for routing rules management
 */

import { RoutingRulesView } from "./views/routingRulesView";

export default function RoutingRulesPage() {
	return (
		<div className="no-padding-parent mx-auto flex h-[calc(var(--app-content-viewport)_-_var(--app-bottom-padding))] min-h-0 w-full flex-col overflow-hidden p-4">
			<RoutingRulesView />
		</div>
	);
}import { createFileRoute, Outlet, useChildMatches } from "@tanstack/react-router";
import { NoPermissionView } from "@/components/noPermissionView";
import { RbacOperation, RbacResource, useRbac } from "@enterprise/lib";
import RoutingRulesPage from "./page";

function RouteComponent() {
	const hasRoutingRulesAccess = useRbac(RbacResource.RoutingRules, RbacOperation.View);
	const childMatches = useChildMatches();
	if (!hasRoutingRulesAccess) {
		return <NoPermissionView entity="routing rules" />;
	}
	return childMatches.length === 0 ? <RoutingRulesPage /> : <Outlet />;
}

export const Route = createFileRoute("/workspace/routing-rules")({
	component: RouteComponent,
});

